import type { MCQQuestion } from '@/types';

// ── Biology ──────────────────────────────────────────────────────────────────
const biology: MCQQuestion[] = [
  { question: 'What is the main function of mitochondria?', options: ['Protein synthesis', 'ATP production via aerobic respiration', 'Cell division', 'Photosynthesis'], answer: 1, explanation: 'Mitochondria carry out aerobic respiration to produce ATP — the cell\'s main energy currency.', topic: 'Cell Biology' },
  { question: 'Which type of cell division produces gametes?', options: ['Mitosis', 'Binary fission', 'Meiosis', 'Amitosis'], answer: 2, explanation: 'Meiosis produces four genetically different haploid cells (gametes). Mitosis produces two identical diploid cells.', topic: 'Genetics' },
  { question: 'Which blood vessel carries oxygenated blood from the lungs to the heart?', options: ['Pulmonary artery', 'Aorta', 'Pulmonary vein', 'Vena cava'], answer: 2, explanation: 'The pulmonary vein is the only vein that carries oxygenated blood — from the lungs back to the left atrium.', topic: 'Organisation' },
  { question: 'Which is the correct word equation for aerobic respiration?', options: ['Glucose → lactic acid + energy', 'Glucose + oxygen → carbon dioxide + water + energy', 'Carbon dioxide + water → glucose + oxygen', 'Glucose → ethanol + carbon dioxide'], answer: 1, explanation: 'Aerobic respiration: glucose + oxygen → carbon dioxide + water (+ ATP). It releases the most energy per glucose molecule.', topic: 'Bioenergetics' },
  { question: 'Which organelle carries out photosynthesis?', options: ['Mitochondria', 'Nucleus', 'Ribosome', 'Chloroplast'], answer: 3, explanation: 'Chloroplasts contain chlorophyll, which absorbs light energy for photosynthesis.', topic: 'Bioenergetics' },
  { question: 'What does DNA stand for?', options: ['Deoxyribonucleic acid', 'Diribonucleic acid', 'Deoxyribosome acid', 'Dinucleic ribose acid'], answer: 0, explanation: 'DNA (Deoxyribonucleic acid) is the molecule that carries genetic information in all living organisms.', topic: 'Genetics' },
  { question: 'Which chromosome combination results in a male offspring?', options: ['XX', 'XY', 'YY', 'XO'], answer: 1, explanation: 'Males have one X and one Y sex chromosome (XY). Females have two X chromosomes (XX).', topic: 'Genetics' },
  { question: 'What is osmosis?', options: ['Movement of solutes from low to high concentration', 'Movement of water through a partially permeable membrane from high to low water potential', 'Active transport of ions against a concentration gradient', 'Diffusion of oxygen into cells'], answer: 1, explanation: 'Osmosis is the movement of water molecules from a region of high water potential to low water potential through a partially permeable membrane.', topic: 'Cell Biology' },
  { question: 'What enzyme in saliva begins the digestion of starch?', options: ['Protease', 'Lipase', 'Amylase', 'Catalase'], answer: 2, explanation: 'Amylase breaks starch down into maltose in the mouth and small intestine.', topic: 'Organisation' },
  { question: 'Which part of the brain controls balance and coordination?', options: ['Cerebrum', 'Medulla', 'Hypothalamus', 'Cerebellum'], answer: 3, explanation: 'The cerebellum coordinates muscle movements and maintains balance.', topic: 'Homeostasis' },
  { question: 'What term describes the maximum population an ecosystem can sustainably support?', options: ['Biotic potential', 'Carrying capacity', 'Population density', 'Ecological niche'], answer: 1, explanation: 'Carrying capacity is the maximum population size that the available resources can support long-term.', topic: 'Ecology' },
  { question: 'Which hormone stimulates liver cells to convert glucose into glycogen?', options: ['Adrenaline', 'Oestrogen', 'Insulin', 'Glucagon'], answer: 2, explanation: 'Insulin is released by the pancreas when blood glucose is high; it promotes storage as glycogen.', topic: 'Homeostasis' },
  { question: 'What is the process by which populations change over generations due to natural selection?', options: ['Speciation', 'Variation', 'Adaptation', 'Evolution'], answer: 3, explanation: 'Evolution is the change in inherited characteristics of a population over successive generations.', topic: 'Genetics & Evolution' },
  { question: 'Which pathogen type is targeted by antibiotics?', options: ['Viruses', 'Bacteria', 'Fungi', 'Protists'], answer: 1, explanation: 'Antibiotics kill or inhibit bacteria. They have no effect on viruses.', topic: 'Infection & Response' },
  { question: 'What is the function of root hair cells?', options: ['Photosynthesis', 'Absorbing water and mineral ions from the soil', 'Transporting glucose', 'Producing oxygen'], answer: 1, explanation: 'Root hair cells have a large surface area to maximise absorption of water (by osmosis) and minerals (by active transport).', topic: 'Organisation' },
];

// ── Chemistry ─────────────────────────────────────────────────────────────────
const chemistry: MCQQuestion[] = [
  { question: 'What is the atomic number of carbon?', options: ['4', '6', '12', '8'], answer: 1, explanation: 'Carbon has 6 protons in its nucleus, so its atomic number is 6. The mass number 12 refers to the total of protons + neutrons.', topic: 'Atomic Structure' },
  { question: 'Which type of bonding involves the sharing of electron pairs?', options: ['Ionic bonding', 'Metallic bonding', 'Covalent bonding', 'Hydrogen bonding'], answer: 2, explanation: 'In covalent bonding, atoms share pairs of electrons. Ionic bonding involves electron transfer.', topic: 'Bonding' },
  { question: 'What is the pH of a neutral solution at 25 °C?', options: ['0', '7', '14', '1'], answer: 1, explanation: 'pH 7 is neutral. Below 7 is acidic; above 7 is alkaline.', topic: 'Chemical Changes' },
  { question: 'Which gas is produced at the cathode when dilute sulfuric acid is electrolysed?', options: ['Oxygen', 'Chlorine', 'Hydrogen', 'Carbon dioxide'], answer: 2, explanation: 'At the cathode (negative electrode), H⁺ ions are reduced to hydrogen gas: 2H⁺ + 2e⁻ → H₂', topic: 'Chemical Changes' },
  { question: 'Which of the following is a mixture?', options: ['Water (H₂O)', 'Iron (Fe)', 'Sodium chloride (NaCl)', 'Air'], answer: 3, explanation: 'Air is a mixture of gases (mainly nitrogen and oxygen). The others are pure substances.', topic: 'Pure Substances & Mixtures' },
  { question: 'What type of reaction occurs when an acid reacts with a metal oxide?', options: ['Oxidation', 'Reduction', 'Neutralisation', 'Decomposition'], answer: 2, explanation: 'Acid + base (metal oxide) → salt + water. This is a neutralisation reaction.', topic: 'Chemical Changes' },
  { question: 'What is the relative formula mass (Mr) of CO₂? (C = 12, O = 16)', options: ['28', '44', '32', '40'], answer: 1, explanation: 'Mr(CO₂) = 12 + (2 × 16) = 12 + 32 = 44 g/mol', topic: 'Quantitative Chemistry' },
  { question: 'Which group of the periodic table contains sodium (Na)?', options: ['Group 7', 'Group 0', 'Group 1', 'Group 2'], answer: 2, explanation: 'Sodium is in Group 1 (the alkali metals). Group 1 metals have one electron in their outer shell.', topic: 'Periodic Table' },
  { question: 'Which gas is produced when hydrochloric acid reacts with zinc?', options: ['Oxygen', 'Carbon dioxide', 'Hydrogen', 'Nitrogen'], answer: 2, explanation: 'Zn + 2HCl → ZnCl₂ + H₂. The squeaky pop test confirms hydrogen gas.', topic: 'Chemical Changes' },
  { question: 'What is the charge of a proton?', options: ['-1', '0', '+1', '+2'], answer: 2, explanation: 'Protons have a relative charge of +1. Neutrons are neutral (0). Electrons are -1.', topic: 'Atomic Structure' },
  { question: 'Which property is characteristic of ionic compounds in solution?', options: ['They do not conduct electricity', 'They have very low melting points', 'They conduct electricity when dissolved in water', 'They are always coloured'], answer: 2, explanation: 'When dissolved, ionic compounds dissociate into free ions which can carry charge and conduct electricity.', topic: 'Bonding' },
  { question: 'What type of polymer is nylon?', options: ['Addition polymer', 'Condensation polymer', 'Natural polymer', 'Thermosetting polymer'], answer: 1, explanation: 'Nylon is made by condensation polymerisation — two monomers react and a small molecule (water) is eliminated.', topic: 'Organic Chemistry' },
  { question: 'What is the name of the process where iron corrodes in the presence of water and oxygen?', options: ['Galvanisation', 'Rusting (oxidation)', 'Reduction', 'Electrolysis'], answer: 1, explanation: 'Rusting is the oxidation of iron: 4Fe + 3O₂ + 6H₂O → 4Fe(OH)₃. Water and oxygen are both required.', topic: 'Chemical Changes' },
  { question: 'What element does the symbol "Cl" represent?', options: ['Calcium', 'Cobalt', 'Chlorine', 'Chromium'], answer: 2, explanation: 'Cl is the symbol for chlorine, a halogen in Group 7 of the periodic table.', topic: 'Periodic Table' },
  { question: 'Which of the following is a product of cracking alkanes?', options: ['A longer alkane and an alcohol', 'A shorter alkane and an alkene', 'Two identical alkenes', 'An alkyne and water'], answer: 1, explanation: 'Cracking breaks long-chain alkanes into shorter alkanes + alkenes. Alkenes are used to make polymers.', topic: 'Organic Chemistry' },
];

// ── Physics ───────────────────────────────────────────────────────────────────
const physics: MCQQuestion[] = [
  { question: 'What is the SI unit of force?', options: ['Joule', 'Watt', 'Newton', 'Pascal'], answer: 2, explanation: 'The Newton (N) is the SI unit of force. 1 N = 1 kg·m/s².', topic: 'Forces' },
  { question: 'Which equation correctly links speed, distance and time?', options: ['speed = distance × time', 'speed = distance ÷ time', 'speed = time ÷ distance', 'speed = distance + time'], answer: 1, explanation: 'Speed (m/s) = distance (m) ÷ time (s). This gives the average speed over a journey.', topic: 'Forces' },
  { question: 'What is the unit of electrical resistance?', options: ['Ampere', 'Volt', 'Watt', 'Ohm'], answer: 3, explanation: 'Resistance is measured in Ohms (Ω). Ohm\'s Law: V = IR, so R = V/I.', topic: 'Electricity' },
  { question: 'Which electromagnetic wave has the highest frequency?', options: ['Radio waves', 'Microwaves', 'Visible light', 'Gamma rays'], answer: 3, explanation: 'The electromagnetic spectrum in order of increasing frequency: radio → micro → infrared → visible → UV → X-ray → gamma.', topic: 'Waves' },
  { question: 'What does the law of conservation of energy state?', options: ['Energy can be created from nothing', 'Energy can be destroyed by nuclear reactions', 'Energy cannot be created or destroyed, only transferred or transformed', 'Energy only exists as thermal energy'], answer: 2, explanation: 'Energy is always conserved — it can change form (e.g. kinetic → thermal) but the total always stays the same.', topic: 'Energy' },
  { question: 'If the length of a metal wire is doubled, what happens to its resistance?', options: ['It halves', 'It stays the same', 'It doubles', 'It quadruples'], answer: 2, explanation: 'Resistance is directly proportional to length: R ∝ L. Doubling the length doubles the resistance.', topic: 'Electricity' },
  { question: 'What is the formula for calculating pressure?', options: ['P = F × A', 'P = F + A', 'P = F ÷ A', 'P = A ÷ F'], answer: 2, explanation: 'Pressure (Pa) = Force (N) ÷ Area (m²). A larger area means lower pressure for the same force.', topic: 'Forces' },
  { question: 'What type of wave is sound?', options: ['Transverse', 'Electromagnetic', 'Longitudinal', 'Torsional'], answer: 2, explanation: 'Sound is a longitudinal wave — compressions and rarefactions travel in the same direction as energy transfer.', topic: 'Waves' },
  { question: 'What is the approximate speed of light in a vacuum?', options: ['3 × 10⁶ m/s', '3 × 10⁸ m/s', '3 × 10¹⁰ m/s', '3 × 10⁴ m/s'], answer: 1, explanation: 'Light (and all EM waves) travel at 3 × 10⁸ m/s in a vacuum. This is the universal speed limit.', topic: 'Waves' },
  { question: 'What is nuclear fission?', options: ['Small nuclei combining to release energy', 'A large nucleus splitting into smaller nuclei, releasing energy', 'Electrons being emitted from a nucleus', 'Protons being absorbed into the nucleus'], answer: 1, explanation: 'Nuclear fission: a large unstable nucleus (e.g. uranium-235) splits into two smaller nuclei, releasing neutrons and energy.', topic: 'Nuclear Physics' },
  { question: 'What is Ohm\'s Law?', options: ['V = I ÷ R', 'V = I + R', 'V = I × R', 'V = R ÷ I'], answer: 2, explanation: 'Ohm\'s Law: Voltage (V) = Current (I) × Resistance (R), provided temperature is constant.', topic: 'Electricity' },
  { question: 'What is the name for the subatomic particle with no charge found in the nucleus?', options: ['Proton', 'Electron', 'Positron', 'Neutron'], answer: 3, explanation: 'Neutrons have no charge and are found in the nucleus alongside protons.', topic: 'Nuclear Physics' },
  { question: 'What is the unit of power?', options: ['Joule', 'Newton', 'Watt', 'Volt'], answer: 2, explanation: 'Power is measured in Watts (W). Power (W) = Energy transferred (J) ÷ Time (s).', topic: 'Energy' },
  { question: 'What does a voltmeter measure?', options: ['Current', 'Resistance', 'Potential difference', 'Power'], answer: 2, explanation: 'A voltmeter measures potential difference (voltage) in volts. It is connected in parallel.', topic: 'Electricity' },
  { question: 'Which type of radiation is stopped by a sheet of paper?', options: ['Beta radiation', 'Gamma radiation', 'X-rays', 'Alpha radiation'], answer: 3, explanation: 'Alpha particles (helium nuclei) are the least penetrating and are stopped by a few centimetres of air or a sheet of paper.', topic: 'Nuclear Physics' },
];

