// ── Mathematics ───────────────────────────────────────────────────────────────
const mathematics: MCQQuestion[] = [
  { question: 'What is 15% of 200?', options: ['20', '25', '30', '35'], answer: 2, explanation: '15% of 200 = (15 ÷ 100) × 200 = 0.15 × 200 = 30', topic: 'Percentages' },
  { question: 'What is the gradient of the line y = 3x + 7?', options: ['7', '3', '10', '1/3'], answer: 1, explanation: 'In y = mx + c, the gradient is m. Here m = 3, and the y-intercept is c = 7.', topic: 'Algebra' },
  { question: 'What is the area of a circle with radius 5 cm? (Use π ≈ 3.14)', options: ['15.7 cm²', '31.4 cm²', '78.5 cm²', '25 cm²'], answer: 2, explanation: 'Area = π r² = 3.14 × 5² = 3.14 × 25 = 78.5 cm²', topic: 'Geometry' },
  { question: 'Solve for x:  2x + 6 = 14', options: ['x = 4', 'x = 10', 'x = 3', 'x = 8'], answer: 0, explanation: '2x = 14 − 6 = 8, so x = 8 ÷ 2 = 4', topic: 'Algebra' },
  { question: 'What does Pythagoras\' theorem state?', options: ['a² − b² = c²', 'a² + b² = c²', 'a + b = c', 'a × b = c²'], answer: 1, explanation: 'In a right-angled triangle: a² + b² = c², where c is the hypotenuse (longest side).', topic: 'Geometry' },
  { question: 'What is the mean of: 5, 10, 15, 20, 25?', options: ['10', '15', '20', '12'], answer: 1, explanation: 'Mean = sum ÷ count = (5+10+15+20+25) ÷ 5 = 75 ÷ 5 = 15', topic: 'Statistics' },
  { question: 'Which of the following is a prime number?', options: ['21', '27', '29', '33'], answer: 2, explanation: '29 is prime — it is only divisible by 1 and itself. 21=3×7, 27=3³, 33=3×11.', topic: 'Number' },
  { question: 'If the probability of an event is 0.3, what is the probability of it NOT occurring?', options: ['0.3', '0.6', '0.7', '1.3'], answer: 2, explanation: 'P(not A) = 1 − P(A) = 1 − 0.3 = 0.7', topic: 'Probability' },
  { question: 'What is the volume of a cube with sides of length 4 cm?', options: ['16 cm³', '32 cm³', '64 cm³', '48 cm³'], answer: 2, explanation: 'Volume = side³ = 4³ = 4 × 4 × 4 = 64 cm³', topic: 'Geometry' },
  { question: 'Expand: (x + 3)(x − 2)', options: ['x² − x − 6', 'x² + x − 6', 'x² + x + 6', 'x² − 6'], answer: 1, explanation: '(x+3)(x−2) = x²−2x+3x−6 = x² + x − 6', topic: 'Algebra' },
  { question: 'What is the value of tan(45°)?', options: ['0', '0.5', '1', '√2'], answer: 2, explanation: 'tan(45°) = sin(45°)/cos(45°) = 1. This is a key trigonometric value to memorise.', topic: 'Trigonometry' },
  { question: 'What is the highest common factor (HCF) of 24 and 36?', options: ['6', '8', '12', '4'], answer: 2, explanation: 'Factors of 24: 1,2,3,4,6,8,12,24. Factors of 36: 1,2,3,4,6,9,12,18,36. HCF = 12.', topic: 'Number' },
  { question: 'Convert 3/8 to a decimal.', options: ['0.25', '0.375', '0.38', '0.4'], answer: 1, explanation: '3 ÷ 8 = 0.375', topic: 'Number' },
  { question: 'What is the equation of a line through the origin with gradient −2?', options: ['y = 2x', 'y = −x + 2', 'y = −2x', 'y = x − 2'], answer: 2, explanation: 'y = mx + c. Gradient = −2 and through origin means c = 0, so y = −2x.', topic: 'Algebra' },
  { question: 'What is 2.5 × 10³ written as an ordinary number?', options: ['25', '250', '2500', '25000'], answer: 2, explanation: '2.5 × 10³ = 2.5 × 1000 = 2500', topic: 'Number' },
];

// ── Computer Science ──────────────────────────────────────────────────────────
const computerScience: MCQQuestion[] = [
  { question: 'What does CPU stand for?', options: ['Central Processing Unit', 'Computer Processing Unit', 'Central Program Utility', 'Core Processing Unit'], answer: 0, explanation: 'The CPU is the main processor of a computer — it carries out instructions from programs.', topic: 'Hardware' },
  { question: 'What is the binary equivalent of decimal 10?', options: ['1000', '1010', '0110', '1100'], answer: 1, explanation: '10 in binary: 8+2 = 1010. The place values are 8,4,2,1 — so 10 = 1×8 + 0×4 + 1×2 + 0×1.', topic: 'Binary' },
  { question: 'Which type of storage loses its contents when the computer is switched off?', options: ['Hard drive', 'SSD', 'ROM', 'RAM'], answer: 3, explanation: 'RAM (Random Access Memory) is volatile — data is lost when power is removed. ROM is non-volatile.', topic: 'Hardware' },
  { question: 'What is an algorithm?', options: ['A computer program', 'A step-by-step set of instructions for solving a problem', 'A type of hardware component', 'A programming language'], answer: 1, explanation: 'An algorithm is a precise sequence of instructions to solve a problem. It can be expressed in pseudocode, flowcharts or code.', topic: 'Programming' },
  { question: 'What does HTML stand for?', options: ['HyperText Machine Language', 'High Text Markup Language', 'HyperText Markup Language', 'Hyperlink and Text Markup Language'], answer: 2, explanation: 'HTML (HyperText Markup Language) is the standard language for creating web pages.', topic: 'Web Technologies' },
  { question: 'Which data type would store the value TRUE or FALSE?', options: ['String', 'Integer', 'Boolean', 'Real'], answer: 2, explanation: 'A Boolean data type can only hold one of two values: TRUE or FALSE. Used in conditions and flags.', topic: 'Programming' },
  { question: 'What is the purpose of an operating system?', options: ['Only to browse the internet', 'To manage hardware and software resources', 'To write programs', 'To store files only'], answer: 1, explanation: 'An OS manages the computer\'s hardware, provides a user interface, manages memory and runs processes.', topic: 'Hardware' },
  { question: 'What is the purpose of encryption?', options: ['To speed up data transfer', 'To compress files', 'To convert data into a secure coded format', 'To delete malware'], answer: 2, explanation: 'Encryption scrambles data so only authorised users with the correct key can read it.', topic: 'Networks & Security' },
  { question: 'What is the output of NOT TRUE in Boolean logic?', options: ['TRUE', 'FALSE', 'UNDEFINED', 'ERROR'], answer: 1, explanation: 'NOT is a logical operator that inverts a Boolean value: NOT TRUE = FALSE, NOT FALSE = TRUE.', topic: 'Logic' },
  { question: 'What is the purpose of a compiler?', options: ['To run programs line by line in real time', 'To translate the entire source code into machine code before execution', 'To automatically debug programs', 'To compress program files'], answer: 1, explanation: 'A compiler translates the whole program into machine code before it runs. An interpreter translates line by line.', topic: 'Programming' },
  { question: 'What is subroutine decomposition?', options: ['Splitting a large problem into smaller manageable subproblems', 'Removing unnecessary code', 'Converting binary to decimal', 'A method of data encryption'], answer: 0, explanation: 'Decomposition breaks a complex problem into smaller parts (subprograms/subroutines), making it easier to design and debug.', topic: 'Programming' },
  { question: 'Which of the following is an example of secondary storage?', options: ['RAM', 'CPU registers', 'Cache', 'Hard drive'], answer: 3, explanation: 'Secondary storage (HDD, SSD, USB) is non-volatile and stores data permanently. RAM is primary/volatile storage.', topic: 'Hardware' },
  { question: 'What does the term "bug" mean in programming?', options: ['A type of virus', 'An intentional program feature', 'An error or flaw in a program', 'A programming language'], answer: 2, explanation: 'A bug is an error in code that causes unexpected behaviour. Debugging is the process of finding and fixing bugs.', topic: 'Programming' },
  { question: 'Which protocol is used to securely transmit data over the internet?', options: ['HTTP', 'FTP', 'HTTPS', 'SMTP'], answer: 2, explanation: 'HTTPS (HyperText Transfer Protocol Secure) uses SSL/TLS encryption, unlike the unencrypted HTTP.', topic: 'Networks & Security' },
  { question: 'What is a LAN?', options: ['A type of processor', 'A Local Area Network connecting devices in a small geographical area', 'A programming language', 'A data type'], answer: 1, explanation: 'A LAN (Local Area Network) connects devices within a limited area such as a school or office.', topic: 'Networks & Security' },
];

// ── History ───────────────────────────────────────────────────────────────────
const history: MCQQuestion[] = [
  { question: 'Who was appointed Chancellor of Germany on 30 January 1933?', options: ['Heinrich Himmler', 'Hermann Göring', 'Adolf Hitler', 'Joseph Goebbels'], answer: 2, explanation: 'President Hindenburg appointed Hitler as Chancellor, believing he could be controlled. This was a critical step in the Nazi seizure of power.', topic: 'Nazi Germany' },
  { question: 'What event in November 1923 was Hitler\'s failed attempt to seize power in Munich?', options: ['The Kapp Putsch', 'The Beer Hall Putsch', 'The Reichstag Fire', 'Kristallnacht'], answer: 1, explanation: 'The Munich (Beer Hall) Putsch failed — Hitler was arrested and sentenced to prison, where he wrote Mein Kampf.', topic: 'Nazi Germany' },
  { question: 'What was the Weimar Republic?', options: ['Germany\'s new democratic government established after WWI', 'Germany\'s empire during WWI', 'A part of the Soviet Union', 'A German political party'], answer: 0, explanation: 'The Weimar Republic (1919–1933) was Germany\'s democratic government following defeat in WWI. It faced major economic and political crises.', topic: 'Weimar Germany' },
  { question: 'What did the Treaty of Versailles (1919) force Germany to accept?', options: ['Gain of new territory', 'War guilt and reparations payments', 'Military expansion rights', 'Leadership of the League of Nations'], answer: 1, explanation: 'The "war guilt clause" (Article 231) blamed Germany for WWI; Germany had to pay £6.6 billion in reparations and lost 13% of its territory.', topic: 'Weimar Germany' },
  { question: 'What was Kristallnacht (November 1938)?', options: ['A Nazi victory parade', 'A coordinated attack on Jewish homes, businesses and synagogues', 'The night Germany invaded Poland', 'Hitler\'s birthday celebration'], answer: 1, explanation: 'Kristallnacht ("Night of Broken Glass") was a nationwide pogrom — over 7,500 Jewish businesses were destroyed and 30,000 Jews arrested.', topic: 'Nazi Germany' },
  { question: 'The Great Depression of 1929 helped Hitler gain support because:', options: ['It strengthened the German economy', 'It caused mass unemployment and discredited the Weimar government', 'It ended reparations payments', 'It made Germany leave the League of Nations'], answer: 1, explanation: 'Unemployment reached 6 million by 1932. Many Germans blamed the Weimar government and turned to extreme parties like the Nazis.', topic: 'Weimar Germany' },
  { question: 'What was the Night of the Long Knives (June 1934)?', options: ['A purge in which the SA leadership was murdered on Hitler\'s orders', 'The assassination of Archduke Franz Ferdinand', 'The invasion of Austria', 'A Soviet attack on Germany'], answer: 0, explanation: 'Hitler ordered the murder of SA leader Ernst Röhm and other rivals to consolidate his power and reassure the German army.', topic: 'Nazi Germany' },
  { question: 'What did the Enabling Act (March 1933) allow Hitler to do?', options: ['Cancel all future elections', 'Pass laws without consulting the Reichstag for four years', 'Take personal command of the army', 'Create the Gestapo'], answer: 1, explanation: 'The Enabling Act gave Hitler the power to pass laws without Reichstag approval, effectively ending democracy in Germany.', topic: 'Nazi Germany' },
  { question: 'Which event triggered the start of World War One (1914)?', options: ['Hitler\'s election as Chancellor', 'The invasion of Poland', 'The assassination of Archduke Franz Ferdinand', 'The Russian Revolution'], answer: 2, explanation: 'Archduke Franz Ferdinand of Austria-Hungary was assassinated in Sarajevo by Gavrilo Princip on 28 June 1914.', topic: 'World War One' },
  { question: 'What was appeasement, as practised by British PM Neville Chamberlain in the 1930s?', options: ['Going to war with Germany early', 'Making concessions to Hitler to avoid another world war', 'Forming a military alliance with the Soviet Union', 'Imposing trade sanctions on Germany'], answer: 1, explanation: 'Appeasement meant giving Hitler what he wanted (e.g. the Sudetenland at Munich, 1938) to avoid war. It is now seen as a failed policy.', topic: 'Causes of WWII' },
  { question: 'What was the Holocaust?', options: ['The bombing of Dresden', 'The systematic genocide of approximately 6 million Jews by the Nazis', 'The siege of Stalingrad', 'The D-Day landings'], answer: 1, explanation: 'The Holocaust was the Nazi regime\'s deliberate murder of around 6 million Jews, alongside millions of others, including Roma, disabled people and political opponents.', topic: 'Nazi Germany' },
  { question: 'What was propaganda under the Nazi regime primarily used for?', options: ['Educating citizens about history', 'Controlling public opinion and spreading Nazi ideology', 'Improving the German economy', 'Building diplomatic relations'], answer: 1, explanation: 'Goebbels\' Ministry of Propaganda controlled all media — newspapers, radio, films and art — to promote Nazi ideas and glorify Hitler.', topic: 'Nazi Germany' },
  { question: 'What percentage of seats did the Nazi Party win in the July 1932 Reichstag elections?', options: ['11%', '37%', '51%', '63%'], answer: 1, explanation: 'The Nazis won 37% of votes in July 1932 — their peak in a free election. They never won an outright majority democratically.', topic: 'Nazi Germany' },
  { question: 'What was the League of Nations?', options: ['A military alliance created after WWI', 'An international organisation created after WWI to maintain peace', 'A European trading agreement', 'The organisation that imposed the Treaty of Versailles'], answer: 1, explanation: 'The League of Nations (1920–1946) aimed to resolve international disputes peacefully. It was weakened by the USA\'s refusal to join.', topic: 'Inter-war Period' },
  { question: 'What was Operation Barbarossa (June 1941)?', options: ['The German invasion of France', 'Germany\'s invasion of the Soviet Union', 'The Allied invasion of Italy', 'Germany\'s naval blockade of Britain'], answer: 1, explanation: 'Operation Barbarossa was Hitler\'s massive invasion of the USSR — a turning point in WWII, eventually leading to German defeat on the Eastern Front.', topic: 'World War Two' },
];

// ── Geography ─────────────────────────────────────────────────────────────────
const geography: MCQQuestion[] = [
  { question: 'What is a fold mountain?', options: ['A mountain formed by volcanic activity', 'A mountain formed when tectonic plates collide and sedimentary rock buckles upward', 'A mountain formed only by erosion', 'A mountain formed from glacial deposits'], answer: 1, explanation: 'Fold mountains (e.g. the Alps, Himalayas) form at convergent plate boundaries when sedimentary layers are compressed and folded.', topic: 'Tectonic Hazards' },
  { question: 'What is a divergent plate boundary?', options: ['Where plates collide and one subducts beneath the other', 'Where plates slide horizontally past each other', 'Where plates move apart from each other', 'Where a plate splits in two'], answer: 2, explanation: 'At divergent boundaries (e.g. Mid-Atlantic Ridge) plates move apart, creating new oceanic crust.', topic: 'Tectonic Hazards' },
  { question: 'What is the greenhouse effect?', options: ['The cooling of the Earth\'s surface by clouds', 'The trapping of heat in the atmosphere by greenhouse gases', 'The process of photosynthesis in forests', 'The reflection of sunlight by the ozone layer'], answer: 1, explanation: 'Greenhouse gases (CO₂, methane) absorb outgoing long-wave radiation and re-radiate it back to Earth, raising surface temperatures.', topic: 'Climate Change' },
  { question: 'What is a floodplain?', options: ['The area of flat land beside a river that is regularly inundated during floods', 'The source of a river in high ground', 'The delta at the mouth of a river', 'The deepest part of a river channel'], answer: 0, explanation: 'Floodplains form as rivers erode laterally and deposit alluvium. They are very fertile but prone to flooding.', topic: 'Rivers' },
  { question: 'What does urbanisation mean?', options: ['The movement of people from cities to the countryside', 'A decrease in city population', 'An increase in the proportion of people living in urban areas', 'The building of new rural settlements'], answer: 2, explanation: 'Urbanisation is driven by rural-to-urban migration and natural population increase in cities. It is fastest in developing countries.', topic: 'Urban Issues' },
  { question: 'What is a pyroclastic flow?', options: ['A stream of slow-moving lava', 'A fast-moving, superheated cloud of gas, ash and volcanic debris', 'A volcanic earthquake', 'A type of glacial flow'], answer: 1, explanation: 'Pyroclastic flows travel at up to 700 km/h and at temperatures over 700°C — one of the most deadly volcanic hazards.', topic: 'Tectonic Hazards' },
  { question: 'What does GDP stand for?', options: ['General Development Plan', 'Geographic Distribution of Population', 'Gross Domestic Product', 'Global Development Programme'], answer: 2, explanation: 'GDP (Gross Domestic Product) is the total monetary value of all goods and services produced in a country in a year — a key measure of economic size.', topic: 'Development' },
  { question: 'What is deforestation?', options: ['Planting new forests', 'The large-scale clearing of forest, typically for agriculture or development', 'The natural death of trees in old forests', 'Government protection of forest areas'], answer: 1, explanation: 'Deforestation (especially in the Amazon) releases stored carbon, reduces biodiversity, and increases soil erosion and flooding.', topic: 'Ecosystems' },
  { question: 'What is a meander?', options: ['A straight section of a fast-flowing river', 'A loop or bend in a river formed by lateral erosion', 'The mouth of a river where it meets the sea', 'The point where a river begins'], answer: 1, explanation: 'Meanders form as rivers erode their outer banks and deposit on inner banks. Over time they can become cut-off oxbow lakes.', topic: 'Rivers' },
  { question: 'What is the Ring of Fire?', options: ['A zone of high volcanic and earthquake activity encircling the Pacific Ocean', 'A volcanic island chain in the Atlantic Ocean', 'A region around the equator with frequent wildfires', 'A deep-sea trench'], answer: 0, explanation: 'The Ring of Fire follows the Pacific Plate boundary — 75% of the world\'s volcanoes and 90% of earthquakes occur here.', topic: 'Tectonic Hazards' },
  { question: 'What is migration?', options: ['Seasonal changes in weather patterns', 'The movement of people from one place to another to live', 'The natural growth of cities', 'The decline in rural birth rates'], answer: 1, explanation: 'Migration can be voluntary (seeking better opportunities) or forced (conflict, climate). It has major impacts on both origin and destination countries.', topic: 'Urban Issues' },
  { question: 'What is the difference between weather and climate?', options: ['They are the same thing', 'Weather is the daily atmospheric conditions; climate is the average over 30+ years', 'Climate is short-term; weather is long-term', 'Weather only refers to temperature'], answer: 1, explanation: 'Weather is what we experience day-to-day; climate is the average pattern of weather conditions over a long period (30+ years).', topic: 'Climate Change' },
  { question: 'What does a high HDI (Human Development Index) indicate?', options: ['A country with high poverty', 'A well-developed country with high life expectancy, education, and income', 'A country with rapid population growth', 'A country with high CO₂ emissions'], answer: 1, explanation: 'HDI combines life expectancy, education (mean and expected years of schooling), and GNI per capita. A value near 1.0 indicates high development.', topic: 'Development' },
  { question: 'What is a sustainable city?', options: ['A city that never grows', 'A city designed to meet current needs without compromising future generations', 'A city with no industry', 'A city entirely powered by solar energy'], answer: 1, explanation: 'Sustainable cities aim to reduce their environmental impact while improving quality of life through green spaces, public transport, and efficient resource use.', topic: 'Urban Issues' },
  { question: 'What is the demographic transition model?', options: ['A graph showing population density', 'A model showing how birth and death rates change as a country develops', 'A model predicting migration patterns', 'A graph of urban vs rural population'], answer: 1, explanation: 'The DTM has 5 stages: from high birth/death rates (Stage 1) to low birth/death rates and ageing populations (Stage 5).', topic: 'Population' },
];

// ── Psychology ────────────────────────────────────────────────────────────────
const psychology: MCQQuestion[] = [
  { question: 'Which psychologist developed classical conditioning through experiments with dogs?', options: ['Sigmund Freud', 'Ivan Pavlov', 'Abraham Maslow', 'B.F. Skinner'], answer: 1, explanation: 'Pavlov conditioned dogs to salivate at the sound of a bell by repeatedly pairing the bell with food — demonstrating classical conditioning.', topic: 'Learning Theories' },
  { question: 'What is the "fight or flight" response?', options: ['A memory consolidation process', 'A physiological response to perceived threat involving adrenaline release', 'A type of cognitive bias', 'A conditioning technique'], answer: 1, explanation: 'The sympathetic nervous system triggers this response: adrenaline is released, heart rate increases, and the body prepares to confront or escape danger.', topic: 'Biological Psychology' },
  { question: 'Which study is famous for investigating obedience to authority?', options: ['Ainsworth\'s Strange Situation', 'Bandura\'s Bobo doll study', 'Milgram\'s electric shock study (1963)', 'Loftus and Palmer\'s car crash study'], answer: 2, explanation: 'Milgram found that 65% of participants delivered the maximum (450V) shock to a confederate when instructed by an authority figure.', topic: 'Social Psychology' },
  { question: 'What is a synapse?', options: ['A type of brain cell (neuron)', 'The gap between two neurons where neurotransmitters are released', 'A region of the spinal cord', 'A type of long-term memory'], answer: 1, explanation: 'At a synapse, an electrical impulse triggers release of neurotransmitters that diffuse across the gap and bind to receptors on the next neuron.', topic: 'Biological Psychology' },
  { question: 'What is the independent variable (IV) in an experiment?', options: ['The variable that is measured', 'The variable that is kept the same', 'The variable that is deliberately changed by the researcher', 'The outcome of the experiment'], answer: 2, explanation: 'The IV is what the researcher manipulates. The dependent variable (DV) is what is measured. Extraneous variables are controlled.', topic: 'Research Methods' },
  { question: 'Which brain structure is primarily associated with memory formation?', options: ['Cerebellum', 'Amygdala', 'Hippocampus', 'Brain stem'], answer: 2, explanation: 'The hippocampus is essential for converting short-term memories to long-term memories (memory consolidation).', topic: 'Biological Psychology' },
  { question: 'What is cognitive dissonance (Festinger)?', options: ['A conflict between two contradictory beliefs or between beliefs and actions, causing discomfort', 'A type of memory loss', 'Learning through observation of others', 'A heightened state of awareness'], answer: 0, explanation: 'Festinger (1957) found that people reduce cognitive dissonance by changing their beliefs, behaviour, or rationalising the inconsistency.', topic: 'Cognitive Psychology' },
  { question: 'Who developed the Hierarchy of Needs theory?', options: ['Carl Jung', 'Sigmund Freud', 'Abraham Maslow', 'B.F. Skinner'], answer: 2, explanation: 'Maslow\'s Hierarchy (1943) suggests basic physiological needs must be met before higher needs (safety, love, esteem, self-actualisation) can be pursued.', topic: 'Approaches in Psychology' },
  { question: 'What does MRI stand for in psychology research?', options: ['Magnetic Resonance Imaging', 'Mental Reasoning Index', 'Memory Response Investigation', 'Multi-Region Imaging'], answer: 0, explanation: 'MRI scanners use magnetic fields and radio waves to produce detailed images of brain structure. fMRI measures brain activity by blood flow.', topic: 'Research Methods' },
  { question: 'What is a phobia?', options: ['An extreme obsession with a thought', 'An intense, irrational and persistent fear of a specific object or situation', 'A positive emotional response to stimuli', 'A type of psychosis'], answer: 1, explanation: 'Phobias are anxiety disorders. They can be treated with systematic desensitisation (classical conditioning) or cognitive behavioural therapy (CBT).', topic: 'Psychopathology' },
];

// ── Sociology ─────────────────────────────────────────────────────────────────
const sociology: MCQQuestion[] = [
  { question: 'What is socialisation?', options: ['Using social media platforms', 'The lifelong process by which individuals learn the norms, values and culture of their society', 'A type of government system', 'The statistical study of social behaviour'], answer: 1, explanation: 'Socialisation begins in the family (primary) and continues through school, peers and media (secondary socialisation).', topic: 'Socialisation' },
  { question: 'Which type of socialisation takes place within the family in early childhood?', options: ['Secondary socialisation', 'Tertiary socialisation', 'Primary socialisation', 'Formal socialisation'], answer: 2, explanation: 'Primary socialisation occurs in the family — children learn basic norms, values, language and gender roles.', topic: 'Socialisation' },
  { question: 'Which sociologist is associated with the functionalist perspective on education?', options: ['Karl Marx', 'Emile Durkheim', 'Max Weber', 'Erving Goffman'], answer: 1, explanation: 'Durkheim argued that education transmits shared norms and values (social solidarity) and prepares individuals for the specialised division of labour.', topic: 'Education' },
  { question: 'What is social stratification?', options: ['A method of studying social issues', 'The hierarchical arrangement of individuals and groups in society by wealth, power or status', 'A type of socialisation process', 'The process of cultural change between generations'], answer: 1, explanation: 'Stratification systems include social class, caste, gender and ethnicity. Sociologists debate whether it is inevitable or unjust.', topic: 'Social Stratification' },
  { question: 'What is Bourdieu\'s concept of "cultural capital"?', options: ['Money earned by cultural industries', 'Knowledge, skills and cultural advantages that can be converted into social advantage', 'Physical assets owned by a family', 'Government funding for the arts'], answer: 1, explanation: 'Bourdieu argued that middle-class children have cultural capital (language, tastes, qualifications) that gives them an advantage in education.', topic: 'Education' },
  { question: 'What does gender socialisation refer to?', options: ['Teaching children about sex education', 'The process by which children learn gender-appropriate behaviours and roles', 'The biological differences between males and females', 'Laws about gender equality in the workplace'], answer: 1, explanation: 'From birth, children are socialised into gender roles through family, toys, media and peer groups.', topic: 'Socialisation' },
  { question: 'What is a longitudinal study?', options: ['A study conducted in one country only', 'A study that follows the same group of people over a long period of time', 'A study using only questionnaires', 'A study comparing different cultures'], answer: 1, explanation: 'Longitudinal studies track changes over time (e.g. years/decades). They are good for studying development but are expensive and subject to sample attrition.', topic: 'Research Methods' },
  { question: 'Which term describes the process where a minority group abandons its original culture and adopts the dominant culture?', options: ['Multiculturalism', 'Cultural diversity', 'Assimilation', 'Secularisation'], answer: 2, explanation: 'Assimilation can be forced or voluntary. Critics argue it leads to loss of cultural identity. Multiculturalism promotes the coexistence of different cultures.', topic: 'Culture & Identity' },
  { question: 'What is the Marxist view of the role of education?', options: ['Education creates equal opportunities for all', 'Education serves the ruling class by reproducing class inequalities and socialising workers to accept their position', 'Education is the main route to social mobility', 'Education is neutral and meritocratic'], answer: 1, explanation: 'Marxists (e.g. Althusser) argue education is an "ideological state apparatus" that reproduces capitalism and teaches workers to accept exploitation.', topic: 'Education' },
  { question: 'What is a social norm?', options: ['A law enforced by the government with legal sanctions', 'An unwritten, shared expectation about how people should behave in society', 'A type of social class', 'A scientific theory about social behaviour'], answer: 1, explanation: 'Norms vary between cultures and groups. Breaking norms leads to informal sanctions (disapproval, exclusion) rather than legal punishment.', topic: 'Culture & Identity' },
];

// ── Business Studies ───────────────────────────────────────────────────────────
const businessStudies: MCQQuestion[] = [
  { question: 'What does USP stand for in marketing?', options: ['Universal Standard Price', 'Unique Selling Point', 'United Sales Plan', 'Uniform Standard Product'], answer: 1, explanation: 'A USP is the feature that distinguishes a product/service from competitors — e.g. Apple\'s design or Amazon\'s delivery speed.', topic: 'Marketing' },
  { question: 'What is the formula for calculating profit?', options: ['Revenue − Total Costs', 'Costs − Revenue', 'Revenue × Costs', 'Revenue + Costs'], answer: 0, explanation: 'Profit = Revenue − Total Costs. If costs exceed revenue, the result is a loss.', topic: 'Finance' },
  { question: 'What is a stakeholder?', options: ['A person who owns shares in a company', 'Anyone with an interest in or affected by a business\'s activities', 'Only the employees of a business', 'Only the customers of a business'], answer: 1, explanation: 'Stakeholders include shareholders, employees, customers, suppliers, the local community and the government — each with different interests.', topic: 'Business Objectives' },
  { question: 'What is the break-even point?', options: ['The point where total costs equal total revenue (zero profit)', 'The point where profit is at its maximum', 'The level of sales that generates the highest revenue', 'The point where revenue equals zero'], answer: 0, explanation: 'At break-even, the firm makes neither a profit nor a loss. Break-even output = Fixed Costs ÷ Contribution per unit.', topic: 'Finance' },
  { question: 'Which type of business organisation has unlimited liability?', options: ['Private limited company (Ltd)', 'Public limited company (plc)', 'Sole trader', 'Cooperative'], answer: 2, explanation: 'Unlimited liability means the owner\'s personal assets can be used to pay business debts. Sole traders and partnerships have unlimited liability.', topic: 'Business Ownership' },
  { question: 'What does SWOT stand for in business analysis?', options: ['Sales, Wages, Operations, Training', 'Strengths, Weaknesses, Opportunities, Threats', 'Strategy, Workforce, Objectives, Targets', 'Supply, Wholesale, Output, Trade'], answer: 1, explanation: 'A SWOT analysis examines internal (Strengths, Weaknesses) and external (Opportunities, Threats) factors affecting a business.', topic: 'Business Strategy' },
  { question: 'What is cash flow?', options: ['The profit of a business over a year', 'The movement of money into and out of a business over time', 'The total revenue of a business', 'The net value of business assets'], answer: 1, explanation: 'Cash flow ≠ profit. A business can be profitable but still fail due to poor cash flow (not having cash when bills are due).', topic: 'Finance' },
  { question: 'What is the purpose of market research?', options: ['To identify and understand customer needs and market conditions before making decisions', 'To set prices for all products', 'To manage employee performance reviews', 'To control production costs'], answer: 0, explanation: 'Market research (primary: surveys/interviews; secondary: published data) reduces risk by informing decisions on product, price, place and promotion.', topic: 'Marketing' },
  { question: 'What is the "marketing mix"?', options: ['The range of products a business sells', 'The combination of product, price, place and promotion used to market a good or service', 'The total marketing budget', 'A mix of advertising channels'], answer: 1, explanation: 'The 4Ps (Product, Price, Place, Promotion) form the marketing mix. Each element must be coordinated to meet customer needs profitably.', topic: 'Marketing' },
  { question: 'What type of economies of scale occur when a larger firm gets discounts from suppliers?', options: ['Technical economies', 'Managerial economies', 'Purchasing economies', 'Financial economies'], answer: 2, explanation: 'Purchasing (bulk-buying) economies allow large firms to negotiate lower unit costs from suppliers due to large order volumes.', topic: 'Business Growth' },
];

// ── Economics ─────────────────────────────────────────────────────────────────
const economics: MCQQuestion[] = [
  { question: 'What is the law of demand?', options: ['As price falls, quantity demanded falls', 'As price rises, quantity demanded rises', 'As price rises, quantity demanded falls (ceteris paribus)', 'Demand and price are unrelated'], answer: 2, explanation: 'Assuming other factors constant (ceteris paribus), a higher price reduces quantity demanded because goods become relatively less affordable.', topic: 'Demand & Supply' },
  { question: 'What is GDP?', options: ['The total income of all households', 'The total value of goods and services produced in a country in one year', 'Total government spending in a year', 'The rate of price inflation'], answer: 1, explanation: 'GDP (Gross Domestic Product) is the primary measure of economic output and the size of an economy.', topic: 'Macroeconomics' },
  { question: 'What is inflation?', options: ['A decrease in the general price level', 'A sustained increase in the general price level over time', 'An increase in employment levels', 'A decrease in income tax'], answer: 1, explanation: 'Inflation erodes purchasing power. The UK government targets CPI inflation at 2%. High inflation is typically caused by excess demand (demand-pull) or rising costs (cost-push).', topic: 'Macroeconomics' },
  { question: 'What is opportunity cost?', options: ['The full production cost', 'The next best alternative forgone when a choice is made', 'The selling price of a product', 'The total costs of running a business'], answer: 1, explanation: 'Opportunity cost underpins economic decision-making. E.g. choosing to go to university means forgoing the wages from full-time work.', topic: 'Economic Concepts' },
  { question: 'What is a monopoly?', options: ['A market with many competing firms', 'A market dominated by a single firm with significant pricing power', 'A government-controlled market', 'A market with exactly two firms'], answer: 1, explanation: 'A pure monopoly has 100% market share. In the UK, a firm with 25%+ market share can be investigated for monopoly power.', topic: 'Market Structures' },
  { question: 'What does fiscal policy refer to?', options: ['Central bank interest rates', 'Government spending and taxation decisions', 'Trade agreements with other countries', 'Exchange rate management'], answer: 1, explanation: 'Fiscal policy is managed by the government. Expansionary fiscal policy increases spending/cuts taxes to stimulate growth; contractionary does the opposite.', topic: 'Macroeconomics' },
  { question: 'What happens to supply when the cost of production falls?', options: ['Supply decreases', 'Supply stays the same', 'Supply increases (supply curve shifts right)', 'Demand increases instead'], answer: 2, explanation: 'Lower production costs mean firms can profitably supply more at each price, shifting the supply curve to the right.', topic: 'Demand & Supply' },
  { question: 'What is free trade?', options: ['Trade that requires no transport costs', 'International trade without tariffs, quotas or subsidies', 'Trade only within a country', 'Trade subsidised by the government'], answer: 1, explanation: 'Free trade (e.g. within the WTO or EU Single Market) allows countries to specialise according to comparative advantage.', topic: 'International Trade' },
  { question: 'What is the role of the Bank of England?', options: ['To manage all UK government spending', 'To act as the UK\'s central bank, setting monetary policy and interest rates', 'To provide loans to businesses', 'To manage the stock market'], answer: 1, explanation: 'The Bank of England sets the base interest rate to meet the 2% inflation target. It also acts as "lender of last resort" to banks.', topic: 'Macroeconomics' },
  { question: 'What is a price elastic demand?', options: ['When demand does not change with price', 'When a small price change causes a proportionally larger change in quantity demanded', 'When supply exceeds demand', 'When demand changes only with income'], answer: 1, explanation: 'PED > 1 = elastic. Luxury goods and those with close substitutes tend to be price elastic; necessities tend to be inelastic.', topic: 'Demand & Supply' },
];

// ── French (grammar) ──────────────────────────────────────────────────────────
const french: MCQQuestion[] = [
  { question: 'How do you say "I am going" in French?', options: ['Je vais', 'Je suis allé', 'J\'irai', 'Je vaille'], answer: 0, explanation: '"Aller" is irregular in the present tense: je vais, tu vas, il/elle va, nous allons, vous allez, ils/elles vont.', topic: 'Verbs' },
  { question: 'How do you form the passé composé of "aller"?', options: ['J\'ai allé', 'Je suis allé(e)', 'J\'allais', 'J\'irai'], answer: 1, explanation: '"Aller" takes "être" as its auxiliary verb in the passé composé. The past participle "allé" agrees with the subject\'s gender.', topic: 'Tenses' },
  { question: 'What does "je ne ... pas" mean in French?', options: ['I often...', 'I don\'t / I do not...', 'I always...', 'I never...'], answer: 1, explanation: 'French negation: "ne...pas" wraps around the verb (or auxiliary in compound tenses): "Je ne mange pas" = "I don\'t eat".', topic: 'Grammar' },
  { question: 'What is the correct French for "the big house" (feminine noun)?', options: ['La maison grand', 'Le grand maison', 'La grande maison', 'Le grande maison'], answer: 2, explanation: 'Adjectives in French agree in gender and number. "Maison" is feminine, so "grand" becomes "grande". Adjectives usually follow the noun, but "grand" precedes it.', topic: 'Grammar' },
  { question: 'What tense is "je mangeais" (I was eating)?', options: ['Present', 'Future', 'Conditional', 'Imperfect (imparfait)'], answer: 3, explanation: 'The imperfect describes ongoing/habitual past actions. It is formed with the stem of the "nous" present form + imperfect endings (-ais, -ais, -ait...).', topic: 'Tenses' },
  { question: 'What does "il faut" mean in French?', options: ['He wants', 'He must', 'It is necessary / one must', 'He can'], answer: 2, explanation: '"Il faut" is an impersonal expression meaning "it is necessary" or "one must". It is followed by an infinitive: "il faut étudier" = you must study.', topic: 'Vocabulary' },
  { question: 'What is the French word for "because"?', options: ['Donc (therefore)', 'Mais (but)', 'Parce que', 'Quand (when)'], answer: 2, explanation: '"Parce que" introduces a reason clause. Other connectives: "donc" (so/therefore), "car" (for/because), "puisque" (since).', topic: 'Connectives' },
  { question: 'Which pronoun replaces a direct object (e.g. "the book") in a French sentence?', options: ['Lui', 'Le/La/Les', 'Y', 'En'], answer: 1, explanation: 'Direct object pronouns: me, te, le/la/l\', nous, vous, les. "Y" replaces a place/indirect object with "à"; "En" replaces "de" + noun.', topic: 'Grammar' },
  { question: 'How do you say "I would like" in French (polite request)?', options: ['Je veux', 'Je voudrais', 'Je voulais', 'Je voulus'], answer: 1, explanation: '"Je voudrais" is the conditional form of "vouloir" and is more polite than "je veux" (I want). Useful in shops and restaurants.', topic: 'Verbs' },
  { question: 'What is the French word for "yesterday"?', options: ['Demain', 'Aujourd\'hui', 'Hier', 'Avant-hier'], answer: 2, explanation: 'Key time expressions: hier (yesterday), aujourd\'hui (today), demain (tomorrow), avant-hier (day before yesterday).', topic: 'Vocabulary' },
];

// ── Spanish (grammar) ─────────────────────────────────────────────────────────
const spanish: MCQQuestion[] = [
  { question: 'How do you say "I speak" in Spanish?', options: ['Yo hablas', 'Yo habla', 'Yo hablo', 'Yo hablé'], answer: 2, explanation: 'Regular -AR verbs in the present tense: yo hablo, tú hablas, él/ella habla, nosotros hablamos, vosotros habláis, ellos hablan.', topic: 'Verbs' },
  { question: 'What does "¿Cuántos años tienes?" mean?', options: ['What is your name?', 'Where are you from?', 'How old are you?', 'How are you?'], answer: 2, explanation: '"Tener" is used for age in Spanish: "Tengo 16 años" = I am 16 years old. "¿Cuántos años tienes?" literally = "How many years do you have?"', topic: 'Vocabulary' },
  { question: 'What is the correct form of "gustar" for "I like apples"?', options: ['Me gusto las manzanas', 'Me gustan las manzanas', 'Me gusta las manzanas', 'Yo gusto las manzanas'], answer: 1, explanation: '"Gustar" agrees with the thing liked, not the person. "Las manzanas" is plural, so use "me gustan" not "me gusta".', topic: 'Grammar' },
  { question: 'How do you say "I have studied" in Spanish (present perfect)?', options: ['Yo estudié', 'Yo había estudiado', 'Yo he estudiado', 'Yo estudio'], answer: 2, explanation: 'Present perfect: subject + haber (present) + past participle. "He estudiado" = I have studied. -ar verbs: past participle ends in -ado.', topic: 'Tenses' },
  { question: 'What does "siempre" mean in Spanish?', options: ['Sometimes', 'Never', 'Always', 'Rarely'], answer: 2, explanation: 'Frequency adverbs: siempre (always), a veces (sometimes), nunca (never), normalmente (usually), raramente (rarely).', topic: 'Vocabulary' },
  { question: 'What does "hay" mean in Spanish?', options: ['Yes', 'There is / there are', 'He has', 'Today'], answer: 1, explanation: '"Hay" is an impersonal form of "haber" meaning "there is" or "there are". "Había" means "there was/were".', topic: 'Grammar' },
  { question: 'How do you say "I am going to eat" using the immediate future in Spanish?', options: ['Como', 'Comeré', 'Comía', 'Voy a comer'], answer: 3, explanation: 'Immediate future: ir (conjugated) + a + infinitive. "Voy a comer" = I am going to eat. "Comeré" is the simple future.', topic: 'Tenses' },
  { question: 'What is the Spanish word for "because"?', options: ['Y (and)', 'Pero (but)', 'Porque', 'Cuando (when)'], answer: 2, explanation: '"Porque" introduces a reason clause. "Por qué" (two words) is the question word "why?". Do not confuse them!', topic: 'Connectives' },
  { question: 'What tense is "yo comía" (I was eating/I used to eat)?', options: ['Preterite', 'Future', 'Imperfect', 'Present'], answer: 2, explanation: 'The imperfect describes ongoing or habitual past actions. -ER/-IR imperfect: -ía, -ías, -ía, -íamos, -íais, -ían.', topic: 'Tenses' },
  { question: 'What is the correct negative sentence in Spanish for "I don\'t eat meat"?', options: ['Yo no como carne', 'Yo como no carne', 'No yo como carne', 'Yo como carne no'], answer: 0, explanation: 'In Spanish, place "no" directly before the verb: "Yo no como carne". Double negatives are correct in Spanish: "No como nada" = I don\'t eat anything.', topic: 'Grammar' },
];

// ── English Language ──────────────────────────────────────────────────────────
const englishLanguage: MCQQuestion[] = [
  { question: 'What is a simile?', options: ['A word that imitates a sound', 'A comparison using "like" or "as"', 'Giving human qualities to non-human things', 'Deliberate repetition of a consonant sound'], answer: 1, explanation: 'Simile: "Her eyes were like stars." Metaphor says something IS something else. Both create vivid imagery.', topic: 'Language Techniques' },
  { question: 'What is sibilance?', options: ['The repetition of vowel sounds', 'The repetition of "s" and "sh" sounds to create a hissing effect', 'Using very long sentences for effect', 'Short, sharp sentences for impact'], answer: 1, explanation: 'Sibilance (a type of alliteration) uses "s"/"sh" sounds: "the soft, silver, serpentine sea." It can suggest stealth or danger.', topic: 'Language Techniques' },
  { question: 'What does AO1 test in English Language?', options: ['Analysing language techniques', 'Reading, understanding and selecting information', 'Writing accurately and effectively', 'Evaluating texts'], answer: 1, explanation: 'AO1 (Reading): identify and interpret explicit and implicit information. AO2: analyse language and structure. AO4: evaluate critically.', topic: 'Exam Skills' },
  { question: 'What is a rhetorical question?', options: ['A question that requires a yes or no answer', 'A question asked for effect, with no answer expected', 'A question that challenges the reader\'s intelligence', 'A question from one character to another'], answer: 1, explanation: 'Rhetorical questions engage and challenge the reader: "Are we really going to let this happen?" They imply an obvious answer.', topic: 'Language Techniques' },
  { question: 'What is the effect of short sentences in non-fiction writing?', options: ['They slow the reader down and create reflection', 'They create pace, urgency or dramatic impact', 'They demonstrate the writer\'s extensive vocabulary', 'They are used only in children\'s writing'], answer: 1, explanation: 'Short sentences can create tension and emphasis. Contrast with long, complex sentences (which can build up detail or feel reflective).', topic: 'Language Techniques' },
  { question: 'What is the purpose of a fronted adverbial?', options: ['To describe a noun', 'To add a subordinate clause at the start of a sentence for variety or emphasis', 'To create a list of items', 'To ask a question'], answer: 1, explanation: 'A fronted adverbial starts the sentence: "Silently, she crept forward." It varies sentence structure and can create atmosphere or emphasis.', topic: 'Grammar & Structure' },
  { question: 'What does the term "register" mean in English?', options: ['The length of a piece of writing', 'The level of formality and style of language appropriate to a situation', 'The genre of a text', 'The point of view in a narrative'], answer: 1, explanation: 'Register shifts between formal (reports, essays), informal (texts, casual speech) and technical language — writers choose register to suit their audience and purpose.', topic: 'Writing' },
  { question: 'What structural technique refers to ideas, images or phrases echoed at the beginning and end of a text?', options: ['Enjambment', 'Juxtaposition', 'Cyclical structure', 'In medias res'], answer: 2, explanation: 'Cyclical structure creates a sense of completion or irony when the ending echoes the opening — common in both fiction and non-fiction.', topic: 'Structure' },
];

// ── English Literature ────────────────────────────────────────────────────────
const englishLiterature: MCQQuestion[] = [
  { question: 'In "Macbeth", what does the dagger hallucination (Act 2 Scene 1) suggest about Macbeth?', options: ['He has always been a murderer', 'His guilty conscience is already affecting him before Duncan\'s murder', 'He is physically ill', 'Lady Macbeth has poisoned him'], answer: 1, explanation: 'The dagger vision shows Macbeth\'s ambivalence and guilt — he sees it as "a dagger of the mind, a false creation / Proceeding from the heat-oppressed brain."', topic: 'Macbeth' },
  { question: 'In "A Christmas Carol", what does the Ghost of Christmas Yet to Come represent?', options: ['Scrooge\'s regrets about the past', 'The consequences of Scrooge\'s miserly behaviour if he does not change', 'The joy of Christmas celebrations', 'The death of Tiny Tim'], answer: 1, explanation: 'The third spirit is silent and shrouded — its silence amplifies dread. It shows a future where Scrooge dies unmourned and Tiny Tim has died. This horror motivates Scrooge\'s transformation.', topic: 'A Christmas Carol' },
  { question: 'In "An Inspector Calls", what is Inspector Goole\'s dramatic function?', options: ['To represent a real police inspector', 'To act as Priestley\'s moral mouthpiece, exposing the Birlings\' social irresponsibility', 'To solve a murder mystery', 'To represent the working class'], answer: 1, explanation: 'Goole (ghoul?) may be supernatural — he knows things before they happen. He represents Priestley\'s socialist message: collective responsibility.', topic: 'An Inspector Calls' },
  { question: 'In "Romeo and Juliet", what is the theme illustrated by the Prince\'s final speech?', options: ['The power of love to overcome hatred', 'That the feud between the families ultimately destroys them both', 'That fate always defeats human free will', 'That religion is more powerful than family loyalty'], answer: 1, explanation: '"All are punished" — the Prince\'s closing words underscore Capulet and Montague\'s joint guilt. The tragedy critiques the social harm of family honour culture.', topic: 'Romeo and Juliet' },
  { question: 'What is the central theme of "Jekyll and Hyde" by Stevenson?', options: ['The dangers of scientific experimentation', 'The duality of human nature — the conflict between respectability and suppressed desires', 'The importance of friendship and loyalty', 'The corrupting effect of wealth'], answer: 1, explanation: 'Stevenson explores how Victorian society\'s rigid respectability drives darker impulses underground. Hyde represents the repressed id; Jekyll the controlled superego.', topic: 'Jekyll and Hyde' },
  { question: 'In "Macbeth", what does the repeated motif of blood symbolise throughout the play?', options: ['Courage and loyalty to Scotland', 'Guilt, violence and the impossibility of escaping the consequences of evil', 'The bravery of the witches\' prophecy', 'Masculinity and strength'], answer: 1, explanation: '"Will all great Neptune\'s ocean wash this blood clean from my hand?" — blood symbolises guilt that cannot be washed away. Lady Macbeth\'s sleepwalking scene ("Out, damned spot") echoes this.', topic: 'Macbeth' },
  { question: 'Which literary term describes giving human characteristics to non-human things?', options: ['Simile', 'Alliteration', 'Personification', 'Hyperbole'], answer: 2, explanation: 'Personification: "The wind whispered through the trees." It creates emotional connections with objects and is common in poetry and descriptive writing.', topic: 'Language Techniques' },
  { question: 'In the AQA GCSE English Literature exam, how many questions are asked about the poem cluster?', options: ['One question on a named poem only', 'One question comparing a named poem to one other poem of the student\'s choice', 'Two questions, one per poem', 'One question with no named poem'], answer: 1, explanation: 'Students are given one poem and asked to compare it to any other poem from the anthology, writing about themes, language, structure and context.', topic: 'Exam Skills' },
];

