// ── German (grammar & vocabulary) ────────────────────────────────────────────
const german: MCQQuestion[] = [
  { question: 'How do you say "I am" in German?', options: ['Ich bin', 'Ich habe', 'Ich bin gewesen', 'Ich war'], answer: 0, explanation: '"Ich bin" is the first-person singular of "sein" (to be) in the present tense.', topic: 'Verbs' },
  { question: 'What is the German word for "and"?', options: ['oder', 'aber', 'und', 'weil'], answer: 2, explanation: '"Und" means "and". "Oder" = or, "aber" = but, "weil" = because.', topic: 'Connectives' },
  { question: 'How do you form the perfect tense of "machen" (to do/make)?', options: ['Ich mache', 'Ich machte', 'Ich habe gemacht', 'Ich werde machen'], answer: 2, explanation: 'The perfect tense uses haben/sein + past participle. "Machen" → "gemacht". Most verbs take haben.', topic: 'Tenses' },
  { question: 'What is the correct German for "the big house" (masculine noun, nominative)?', options: ['Das große Haus', 'Der große Haus', 'Ein großes Haus', 'Das groß Haus'], answer: 0, explanation: '"Haus" is neuter (das). In the nominative, "das große Haus" is correct. Adjective endings change with gender and case.', topic: 'Grammar' },
  { question: 'What does "Ich möchte" mean in German?', options: ['I must', 'I can', 'I would like', 'I should'], answer: 2, explanation: '"Möchte" is the conditional form of "mögen" and means "would like". It is used for polite requests.', topic: 'Modal Verbs' },
  { question: 'What is the German word for "because" (followed by a subordinate clause)?', options: ['denn', 'weil', 'aber', 'trotzdem'], answer: 1, explanation: '"Weil" sends the verb to the end of the clause: "Ich lerne, weil es wichtig ist." "Denn" keeps normal word order.', topic: 'Connectives' },
  { question: 'How do you say "yesterday" in German?', options: ['morgen', 'heute', 'gestern', 'damals'], answer: 2, explanation: 'Key time adverbs: gestern (yesterday), heute (today), morgen (tomorrow), damals (back then).', topic: 'Vocabulary' },
  { question: 'Which article is used with masculine nouns in the nominative case?', options: ['die', 'das', 'der', 'den'], answer: 2, explanation: '"Der" is the definite article for masculine nouns in the nominative. Die = feminine/plural, das = neuter.', topic: 'Grammar' },
  { question: 'What tense is "Er spielte Fußball"?', options: ['Present', 'Perfect', 'Simple past (Imperfekt)', 'Future'], answer: 2, explanation: 'The Imperfekt (simple past) is formed by adding -te endings to weak verbs: spielen → spielte. Common in written German.', topic: 'Tenses' },
  { question: 'What does "obwohl" mean in German?', options: ['because', 'although/even though', 'so that', 'if'], answer: 1, explanation: '"Obwohl" means "although" and introduces a subordinate clause, sending the verb to the end: "Obwohl es regnet, gehe ich raus."', topic: 'Connectives' },
];

// ── Chinese (vocabulary & grammar) ───────────────────────────────────────────
const chinese: MCQQuestion[] = [
  { question: 'How do you say "Hello" in Mandarin Chinese?', options: ['Zàijiàn', 'Xièxiè', 'Nǐ hǎo', 'Duìbuqǐ'], answer: 2, explanation: '"Nǐ hǎo" (你好) is the standard greeting meaning "you good/hello". "Zàijiàn" = goodbye, "Xièxiè" = thank you.', topic: 'Greetings' },
  { question: 'What is the Mandarin word for "I" or "me"?', options: ['Nǐ', 'Wǒ', 'Tā', 'Wǒmen'], answer: 1, explanation: '"Wǒ" (我) = I/me. "Nǐ" = you, "tā" = he/she/it, "wǒmen" = we.', topic: 'Pronouns' },
  { question: 'How do you say "Thank you" in Mandarin?', options: ['Duìbuqǐ', 'Nǐ hǎo', 'Xièxiè', 'Bù kèqì'], answer: 2, explanation: '"Xièxiè" (谢谢) means thank you. "Bù kèqì" is the response meaning "you\'re welcome".', topic: 'Vocabulary' },
  { question: 'What does "méiyǒu" (没有) mean in Chinese?', options: ['have/has', 'do not have / there is no', 'very good', 'not yet'], answer: 1, explanation: '"Méiyǒu" is the negation of "yǒu" (to have). It means "do not have" or "there is no".', topic: 'Grammar' },
  { question: 'What number does "shí" (十) represent?', options: ['4', '7', '10', '100'], answer: 2, explanation: 'Numbers: yī(1), èr(2), sān(3), sì(4), wǔ(5), liù(6), qī(7), bā(8), jiǔ(9), shí(10).', topic: 'Numbers' },
  { question: 'How do you ask "How are you?" in Mandarin?', options: ['Nǐ shì shéi?', 'Nǐ hǎo ma?', 'Nǐ shì nǎlǐ rén?', 'Nǐ jiào shénme míngzi?'], answer: 1, explanation: '"Nǐ hǎo ma?" (你好吗?) adds the question particle "ma" to "nǐ hǎo" to form a yes/no question.', topic: 'Greetings' },
  { question: 'What is the Mandarin word for "school"?', options: ['Yīyuàn', 'Xuéxiào', 'Shāngdiàn', 'Tú shū guǎn'], answer: 1, explanation: '"Xuéxiào" (学校) means school. "Yīyuàn" = hospital, "shāngdiàn" = shop, "túshūguǎn" = library.', topic: 'Vocabulary' },
  { question: 'How do you express "I like" in Mandarin?', options: ['Wǒ xiǎng', 'Wǒ xǐhuān', 'Wǒ néng', 'Wǒ yào'], answer: 1, explanation: '"Xǐhuān" (喜欢) means to like. "Wǒ xǐhuān..." = I like... "Xiǎng" = want/think, "néng" = can, "yào" = want/need.', topic: 'Vocabulary' },
  { question: 'What does "de" (的) do in a Mandarin sentence?', options: ['It marks the verb', 'It connects a modifier to a noun (possessive/adjective particle)', 'It marks a question', 'It marks negation'], answer: 1, explanation: '"De" (的) is the structural particle connecting adjectives or possessives to nouns: "wǒ de shū" = my book (lit. I de book).', topic: 'Grammar' },
  { question: 'Which word means "today" in Mandarin?', options: ['Míngtiān', 'Zuótiān', 'Jīntiān', 'Xiànzài'], answer: 2, explanation: 'Time words: jīntiān (today), míngtiān (tomorrow), zuótiān (yesterday), xiànzài (now).', topic: 'Vocabulary' },
];

// ── Drama ─────────────────────────────────────────────────────────────────────
const drama: MCQQuestion[] = [
  { question: 'What is "Stanislavski\'s Method"?', options: ['A system of physical theatre using masks', 'A naturalistic acting technique where actors draw on personal emotions to create believable characters', 'A style of performance using stylised movement and narration', 'Brechtian techniques for alienating the audience'], answer: 1, explanation: 'Stanislavski developed the Method to help actors create psychologically truthful characters using emotional memory, objectives and given circumstances.', topic: 'Acting' },
  { question: 'What does the term "blocking" mean in theatre?', options: ['Stopping an actor from speaking their lines', 'The planned movement and positioning of actors on stage', 'A rehearsal technique for improvisation', 'The process of learning scripts'], answer: 1, explanation: 'Blocking refers to the pre-planned stage movement: where actors stand, move and face during a performance.', topic: 'Theatre Craft' },
  { question: 'What is "Brechtian theatre" known for?', options: ['Creating total emotional immersion and suspension of disbelief', 'Alienation effects (Verfremdungseffekt) to make the audience think critically', 'Using elaborate realistic sets to recreate real environments', 'Focusing only on psychological realism'], answer: 1, explanation: 'Brecht used alienation effects — direct address, placards, visible lighting — to prevent emotional identification and encourage critical thinking.', topic: 'Theatre Practitioners' },
  { question: 'What is a "cyclorama" in theatre?', options: ['A style of comedy theatre', 'A curved background cloth used to represent the sky or create lighting effects', 'A revolving stage', 'A type of spotlight'], answer: 1, explanation: 'A cyclorama (cyc) is a curved white or neutral backdrop lit to suggest sky, distance or colour washes.', topic: 'Design' },
  { question: 'What does "in the round" mean as a stage configuration?', options: ['A curved thrust stage', 'Audience seated on all sides surrounding the performance area', 'A traditional proscenium arch stage', 'A traverse stage with audience on two sides'], answer: 1, explanation: 'Theatre in the round places the audience on all four sides of a central performance space. It creates intimacy but limits set design.', topic: 'Theatre Craft' },
  { question: 'What is "proxemics" in performance?', options: ['The use of sound and music to set mood', 'The use of space and distance between performers to convey meaning', 'A style of physical theatre', 'The study of audience response'], answer: 1, explanation: 'Proxemics examines how physical distance between performers (or between performer and audience) creates meaning and relationship.', topic: 'Performance Skills' },
  { question: 'What is a "soliloquy"?', options: ['A speech delivered by multiple characters in unison', 'A private speech delivered alone on stage, sharing a character\'s inner thoughts with the audience', 'A dialogue between two characters', 'An extended narrative monologue by a narrator'], answer: 1, explanation: 'A soliloquy is a dramatic device where a character speaks private thoughts aloud, as if alone, directly sharing their inner world with the audience.', topic: 'Dramatic Devices' },
  { question: 'What is "physical theatre"?', options: ['Theatre performed outdoors', 'A performance style where physical movement, gesture and body are primary storytelling tools', 'Theatre using only naturalistic acting', 'A style requiring elaborate costumes'], answer: 1, explanation: 'Physical theatre (e.g. DV8, Complicité) uses movement, rhythm and physicality as central storytelling tools, often above or alongside spoken word.', topic: 'Theatre Styles' },
  { question: 'What role does a "dramaturg" play in theatre production?', options: ['They design the lighting rig', 'They research, analyse and develop the intellectual and literary context of a production', 'They direct the actors on stage', 'They manage ticket sales and front of house'], answer: 1, explanation: 'A dramaturg researches context, advises on script development, analyses themes and helps shape the production\'s intellectual and artistic vision.', topic: 'Theatre Craft' },
  { question: 'What is "Artaud\'s Theatre of Cruelty"?', options: ['Theatre designed to make audiences laugh through physical comedy', 'A radical theatre intended to assault the senses and shock audiences into confronting raw human experience', 'A form of puppet theatre', 'A style of theatre using realistic dialogue'], answer: 1, explanation: 'Artaud\'s Theatre of Cruelty aimed to bypass rational thought, using intense sensory experience (sound, light, space) to transform the audience emotionally and spiritually.', topic: 'Theatre Practitioners' },
];

// ── Music ─────────────────────────────────────────────────────────────────────
const music: MCQQuestion[] = [
  { question: 'How many beats are in a 3/4 time signature per bar?', options: ['2', '3', '4', '6'], answer: 1, explanation: 'In 3/4 time, the top number indicates 3 beats per bar, and the bottom number (4) means each beat is a quarter note/crotchet.', topic: 'Rhythm & Metre' },
  { question: 'What does "forte" (f) mean in music?', options: ['Soft', 'Very soft', 'Loud', 'Very loud'], answer: 2, explanation: 'Dynamic markings: pp (very soft) → p (soft) → mp (moderately soft) → mf (moderately loud) → f (loud) → ff (very loud).', topic: 'Dynamics' },
  { question: 'What is the interval between C and G called?', options: ['A third', 'A fourth', 'A fifth', 'A sixth'], answer: 2, explanation: 'C to G spans 5 letter names (C-D-E-F-G), making it a perfect fifth — one of the most consonant intervals.', topic: 'Intervals' },
  { question: 'Which instrument family includes the oboe and bassoon?', options: ['Brass', 'Strings', 'Woodwind', 'Percussion'], answer: 2, explanation: 'The oboe and bassoon are double-reed woodwind instruments. The clarinet and flute are also woodwinds but use single reeds or open mouthpieces.', topic: 'Instruments' },
  { question: 'What does "allegro" mean as a tempo marking?', options: ['Slow and stately', 'At a walking pace', 'Fast and lively', 'Very fast'], answer: 2, explanation: 'Tempo markings from slow to fast: Grave → Largo → Adagio → Andante → Moderato → Allegro → Vivace → Presto → Prestissimo.', topic: 'Tempo' },
  { question: 'What is a "chord"?', options: ['A single sustained note', 'Three or more notes played simultaneously', 'A scale pattern', 'A rhythmic pattern'], answer: 1, explanation: 'A chord is formed when three or more different pitches sound together. The most basic chord is a triad (root, third, fifth).', topic: 'Harmony' },
  { question: 'What is the role of the "walking bass" in jazz?', options: ['A loud, accented bass line', 'A steady 4-to-a-bar bass line that moves step-wise through chord tones to drive the rhythm', 'A bass ostinato that repeats exactly', 'A bass line that only plays on beats 1 and 3'], answer: 1, explanation: 'A walking bass provides harmonic rhythm and forward momentum in jazz, moving smoothly between chord tones and passing notes on each beat.', topic: 'Jazz' },
  { question: 'What is a "riff" in popular music?', options: ['An extended improvised solo', 'A short, repeated, memorable melodic or rhythmic pattern', 'The chorus of a song', 'A type of drum fill'], answer: 1, explanation: 'A riff is a short, catchy musical phrase that is repeated as a foundation or hook. Famous riffs: Satisfaction (Rolling Stones), Smoke on the Water (Deep Purple).', topic: 'Pop & Rock' },
  { question: 'What characterises Baroque music (1600–1750)?', options: ['Use of electronic instruments and synthesisers', 'Ornate ornamentation, basso continuo, terraced dynamics and polyphonic texture', 'Simple folk melodies with guitar accompaniment', 'Minimalist repetitive patterns'], answer: 1, explanation: 'Baroque composers (Bach, Handel, Vivaldi) used basso continuo, ornate decorations, terraced dynamics (sudden changes) and complex counterpoint.', topic: 'Western Classical' },
  { question: 'What is "call and response"?', options: ['A solo instrument playing against a full orchestra', 'A musical conversation where one phrase ("call") is answered by a second phrase ("response")', 'A type of round or canon', 'A theme and variations structure'], answer: 1, explanation: 'Call and response is a structural device common in African music, blues, gospel and jazz where a melodic statement is answered by a counter-phrase.', topic: 'Structure' },
];

// ── Art & Design ──────────────────────────────────────────────────────────────
